"""Owned Prometheus3.5 TSDB backfill, no scrape targets or external network."""
import base64,hashlib,json,os,pathlib,socket,subprocess,tempfile,time,urllib.error,urllib.request

class HistoricalPrometheus:
 def __init__(self,samples):self.samples=samples;self.proc=None;self.log=None
 def __enter__(self):
  self.temp=tempfile.TemporaryDirectory(prefix='of-prom-history-');self.root=pathlib.Path(self.temp.name)
  try:
   with socket.socket() as sock:sock.bind(('127.0.0.1',0));self.port=sock.getsockname()[1]
   self.base='http://127.0.0.1:'+str(self.port);data=self.root/'data';data.mkdir()
   raw=pathlib.Path(__file__).with_name('prometheus_short_peak_fixture.json').read_bytes()
   assert hashlib.sha256(raw).hexdigest()=='3731c4fb2f33ec45605f00fa3ac3f468464c7ca73d282d859637638921486c12'
   asset=json.loads(raw);assert self.samples==asset['samples'] and len(self.samples)==61
   for row in asset['files']:
    parts=pathlib.PurePosixPath(row['path']).parts;assert len(parts) in (2,3) and not any(p in ('..','.','') for p in parts)
    content=base64.b64decode(row['base64'],validate=True);assert len(content)==row['bytes'] and hashlib.sha256(content).hexdigest()==row['sha256']
    path=data.joinpath(*parts);path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(content)
   version=subprocess.check_output(['prometheus','--version'],stderr=subprocess.STDOUT,text=True,timeout=3);assert 'version 3.5.' in version
   env={**os.environ,'GOMAXPROCS':'2','GOMEMLIMIT':'128MiB'}
   config=self.root/'prometheus.json'
   config.write_text(json.dumps({'global':{'scrape_interval':'5s','evaluation_interval':'5s'},'scrape_configs':[]}))
   self.log=(self.root/'server.log').open('wb')
   self.proc=subprocess.Popen(['prometheus','--config.file='+str(config),'--storage.tsdb.path='+str(data),'--storage.tsdb.retention.time=100y','--storage.tsdb.wal-segment-size=10MB','--query.max-concurrency=2','--web.listen-address=127.0.0.1:'+str(self.port),'--log.level=error'],env=env,stdout=self.log,stderr=self.log)
   deadline=time.monotonic()+10
   while time.monotonic()<deadline:
    assert self.proc.poll() is None,'private Prometheus exited'
    try:
     self.request('/-/ready');print('NATIVE_PROMETHEUS_HISTORY_READY:3.5-private-backfilled-tsdb',flush=True);return self
    except (OSError,urllib.error.URLError):time.sleep(.05)
   raise RuntimeError('private historical Prometheus readiness timeout')
  except BaseException:self.__exit__(None,None,None);raise
 def request(self,path):
  opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
  with opener.open(self.base+path,timeout=3) as response:
   data=response.read();return json.loads(data) if 'json' in response.headers.get('Content-Type','') else data
 def __exit__(self,*args):
  if self.proc is not None and self.proc.poll() is None:
   self.proc.terminate()
   try:self.proc.wait(timeout=3)
   except subprocess.TimeoutExpired:self.proc.kill();self.proc.wait(timeout=2)
  if self.log:self.log.close()
  self.temp.cleanup()
